namespace sv_49bce1f9db6f46869889a84ca6c969bb.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_49bce1f9db6f46869889a84ca6c969bb.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="nav flex-column">
        @foreach (var (label, index) in Sections.Select((s, i) => (s, i)))
        {
            <li class="nav-item">
                <button class="nav-link @(index == ActiveIndex ? "active" : "")"
                        @onclick="() => OnSectionSelected.InvokeAsync(index)">
                    @label
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired] public int ActiveIndex { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnSectionSelected { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];
}

@namespace sv_49bce1f9db6f46869889a84ca6c969bb.Components.Pages.Settings
@using sv_49bce1f9db6f46869889a84ca6c969bb.Services

<div class="settings-section">
    <h3>Profile</h3>

    <div class="mb-3 text-center">
        @if (!string.IsNullOrEmpty(avatarUrl))
        {
            <img src="@avatarUrl" alt="Avatar" class="rounded-circle mb-2" style="width:80px;height:80px;object-fit:cover;" />
        }
        else
        {
            <div class="rounded-circle bg-secondary d-inline-flex align-items-center justify-content-center mb-2"
                 style="width:80px;height:80px;">
                <span class="text-white">No Avatar</span>
            </div>
        }
        <div class="text-muted small">@avatarUrl</div>
    </div>

    <div class="mb-3">
        <label class="form-label">Display Name</label>
        <input type="text" class="form-control" @bind="displayName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email</label>
        <input type="email" class="form-control" @bind="email" />
    </div>

    <div class="mb-3">
        <label class="form-label">Bio</label>
        <textarea class="form-control" rows="4" @bind="bio"></textarea>
    </div>

    <div class="d-flex gap-2">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
            @(saving ? "Saving..." : "Save Changes")
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
    </div>

    @if (showSuccess)
    {
        <div class="alert alert-success mt-3 fade show" role="alert">
            Profile saved successfully!
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<UserProfile> OnSave { get; set; }

    private string displayName = "";
    private string email = "";
    private string avatarUrl = "";
    private string bio = "";
    private bool saving;
    private bool showSuccess;

    protected override void OnParametersSet()
    {
        if (!hasInitialized)
        {
            LoadFromProfile();
            hasInitialized = true;
        }
    }

    private bool hasInitialized;

    private void LoadFromProfile()
    {
        displayName = Profile.DisplayName;
        email = Profile.Email;
        avatarUrl = Profile.AvatarUrl;
        bio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        saving = true;
        showSuccess = false;
        var updated = new UserProfile(displayName, email, avatarUrl, bio);
        await OnSave.InvokeAsync(updated);
        saving = false;
        showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        StateHasChanged();
    }

    private void Discard()
    {
        LoadFromProfile();
        showSuccess = false;
    }
}

@namespace sv_49bce1f9db6f46869889a84ca6c969bb.Components.Pages.Settings
@using sv_49bce1f9db6f46869889a84ca6c969bb.Services

<div class="settings-section">
    <h3>Notifications</h3>

    <div class="mb-3 form-check form-switch">
        <input class="form-check-input" type="checkbox" id="emailNotif" @bind="emailNotifications" />
        <label class="form-check-label" for="emailNotif">Email Notifications</label>
    </div>

    <div class="mb-3 form-check form-switch">
        <input class="form-check-input" type="checkbox" id="pushNotif" @bind="pushNotifications" />
        <label class="form-check-label" for="pushNotif">Push Notifications</label>
    </div>

    <div class="mb-3 form-check form-switch">
        <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="weeklyDigest" />
        <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
    </div>

    <hr />
    <h5>Muted Channels</h5>
    @if (allChannels.Count > 0)
    {
        <div class="mb-3">
            @foreach (var channel in allChannels)
            {
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                           checked="@mutedChannels.Contains(channel)"
                           @onchange="(e) => ToggleChannel(channel, (bool)e.Value!)" />
                    <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                </div>
            }
        </div>
    }
    else
    {
        <p class="text-muted">No channels available.</p>
    }

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
        @(saving ? "Saving..." : "Save Preferences")
    </button>

    @if (showSuccess)
    {
        <div class="alert alert-success mt-3 fade show" role="alert">
            Notification preferences saved!
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public NotificationPrefs Prefs { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> allChannels = new();
    private bool saving;
    private bool showSuccess;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        if (!hasInitialized)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
            allChannels = ["general", "announcements", "random", "engineering", "marketing"];
            hasInitialized = true;
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        saving = true;
        showSuccess = false;
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        saving = false;
        showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        StateHasChanged();
    }
}

@namespace sv_49bce1f9db6f46869889a84ca6c969bb.Components.Pages.Settings

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center"
         role="button" @onclick="() => expanded = !expanded">
        <span>Change Password</span>
        <span>@(expanded ? "▲" : "▼")</span>
    </div>
    @if (expanded)
    {
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(errorMessage))
            {
                <div class="alert alert-danger">@errorMessage</div>
            }
            @if (showSuccess)
            {
                <div class="alert alert-success">Password updated successfully!</div>
            }

            <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@updating">
                @(updating ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool expanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? errorMessage;
    private bool updating;
    private bool showSuccess;

    private async Task UpdatePasswordAsync()
    {
        errorMessage = null;
        showSuccess = false;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            errorMessage = "All password fields are required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            errorMessage = "New password and confirmation do not match.";
            return;
        }

        updating = true;
        try
        {
            await OnChangePassword.InvokeAsync((currentPassword, newPassword));
            showSuccess = true;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            updating = false;
        }
    }
}

@namespace sv_49bce1f9db6f46869889a84ca6c969bb.Components.Pages.Settings
@using sv_49bce1f9db6f46869889a84ca6c969bb.Services

<div class="mb-3">
    <h5>Active Sessions</h5>
    <div class="table-responsive">
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                @if (confirmingSessionId == session.Id)
                                {
                                    <span class="me-2">Revoke this session?</span>
                                    <button class="btn btn-sm btn-danger me-1" @onclick="() => ConfirmRevoke(session.Id)">
                                        Yes
                                    </button>
                                    <button class="btn btn-sm btn-outline-secondary" @onclick="CancelRevoke">
                                        No
                                    </button>
                                }
                                else
                                {
                                    <button class="btn btn-sm btn-outline-danger" @onclick="() => RequestRevoke(session.Id)">
                                        Revoke
                                    </button>
                                }
                            }
                            else
                            {
                                <span class="badge bg-success">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnRevoke { get; set; }

    private string? confirmingSessionId;

    private void RequestRevoke(string sessionId)
    {
        confirmingSessionId = sessionId;
    }

    private void CancelRevoke()
    {
        confirmingSessionId = null;
    }

    private async Task ConfirmRevoke(string sessionId)
    {
        await OnRevoke.InvokeAsync(sessionId);
        confirmingSessionId = null;
    }
}

