<div class="mb-3">
    <h5>Active Sessions</h5>
    <div class="table-responsive">
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                @if (confirmingSessionId == session.Id)
                                {
                                    <span class="me-2">Revoke this session?</span>
                                    <button class="btn btn-sm btn-danger me-1" @onclick="() => ConfirmRevoke(session.Id)">
                                        Yes
                                    </button>
                                    <button class="btn btn-sm btn-outline-secondary" @onclick="CancelRevoke">
                                        No
                                    </button>
                                }
                                else
                                {
                                    <button class="btn btn-sm btn-outline-danger" @onclick="() => RequestRevoke(session.Id)">
                                        Revoke
                                    </button>
                                }
                            }
                            else
                            {
                                <span class="badge bg-success">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnRevoke { get; set; }

    private string? confirmingSessionId;

    private void RequestRevoke(string sessionId)
    {
        confirmingSessionId = sessionId;
    }

    private void CancelRevoke()
    {
        confirmingSessionId = null;
    }

    private async Task ConfirmRevoke(string sessionId)
    {
        await OnRevoke.InvokeAsync(sessionId);
        confirmingSessionId = null;
    }
}

