@namespace sv_49bce1f9db6f46869889a84ca6c969bb.Components.Pages.Settings
@using sv_49bce1f9db6f46869889a84ca6c969bb.Services

<div class="settings-section">
    <h3>Security</h3>

    <ChangePasswordPanel OnChangePassword="OnChangePassword" />

    <div class="mb-3 form-check form-switch">
        <input class="form-check-input" type="checkbox" id="twoFactor"
               checked="@SecurityData.TwoFactorEnabled" disabled />
        <label class="form-check-label" for="twoFactor">
            Two-Factor Authentication
            @if (SecurityData.TwoFactorEnabled)
            {
                <span class="badge bg-success ms-2">Enabled</span>
            }
            else
            {
                <span class="badge bg-warning ms-2">Disabled</span>
            }
        </label>
    </div>

    @if (SecurityData.LastPasswordChange.HasValue)
    {
        <p class="text-muted small">Last password change: @SecurityData.LastPasswordChange.Value.ToString("f")</p>
    }

    <ActiveSessionsTable Sessions="SecurityData.Sessions"
                         CurrentSessionId="@currentSessionId"
                         OnRevoke="OnRevoke" />
</div>

@code {
    [Parameter, EditorRequired] public SecuritySettings SecurityData { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnRevoke { get; set; }

    private string currentSessionId => SecurityData.Sessions.FirstOrDefault()?.Id ?? "";
}

@namespace sv_49bce1f9db6f46869889a84ca6c969bb.Components.Pages.Settings
@using sv_49bce1f9db6f46869889a84ca6c969bb.Services

<div class="settings-section">
    <h3>Appearance</h3>

    <div class="mb-3">
        <label class="form-label fw-bold">Theme</label>
        <div>
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="theme"
                           id="@($"theme-{theme}")" value="@theme"
                           checked="@(selectedTheme == theme)"
                           @onchange="() => selectedTheme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label fw-bold">Font Size</label>
        <div>
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="fontSize"
                           id="@($"fs-{size}")" value="@size"
                           checked="@(selectedFontSize == size)"
                           @onchange="() => selectedFontSize = size" />
                    <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                </div>
            }
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label fw-bold">Language</label>
        <select class="form-select" @bind="selectedLanguage">
            <option value="en">English</option>
            <option value="es">Español</option>
            <option value="fr">Français</option>
            <option value="de">Deutsch</option>
            <option value="ja">日本語</option>
        </select>
    </div>

    <div class="mb-3 form-check form-switch">
        <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
        <label class="form-check-label" for="compactMode">Compact Mode</label>
    </div>

    <div class="card mb-3">
        <div class="card-header">Live Preview</div>
        <div class="card-body @PreviewClasses" style="@PreviewStyle">
            <h5 class="card-title">Sample Heading</h5>
            <p class="card-text">This is how your content will appear with the selected settings.</p>
            <button class="btn btn-primary btn-sm">Sample Button</button>
        </div>
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
        @(saving ? "Saving..." : "Save")
    </button>

    @if (showSuccess)
    {
        <div class="alert alert-success mt-3 fade show" role="alert">
            Appearance settings saved!
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Settings { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "en";
    private bool compactMode;
    private bool saving;
    private bool showSuccess;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        if (!hasInitialized)
        {
            selectedTheme = Settings.Theme;
            selectedFontSize = Settings.FontSize;
            selectedLanguage = Settings.Language;
            compactMode = Settings.CompactMode;
            hasInitialized = true;
        }
    }

    private string PreviewClasses =>
        (selectedTheme == "Dark" ? "bg-dark text-light" : "bg-light text-dark") +
        (compactMode ? " p-2" : " p-3");

    private string PreviewStyle => selectedFontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.25rem;",
        _ => "font-size: 1rem;"
    };

    private async Task SaveAsync()
    {
        saving = true;
        showSuccess = false;
        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);
        saving = false;
        showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        StateHasChanged();
    }
}

