+                case 1:
+                    <NotificationsSection Prefs="notificationPrefs!" OnSave="SaveNotificationsAsync" />
+                    break;
+                case 2:
+                    <SecuritySection SecurityData="securitySettings!"
+                                     OnChangePassword="ChangePasswordAsync"
+                                     OnRevoke="RevokeSessionAsync" />
+                    break;
+                case 3:
+                    <AppearanceSection Settings="appearanceSettings!" OnSave="SaveAppearanceAsync" />
+                    break;
+            }
+        }
+    </main>
+</div>
+
+@code {
+    private int activeSection;
+    private bool loading = true;
+
+    private UserProfile? profile;
+    private NotificationPrefs? notificationPrefs;
+    private SecuritySettings? securitySettings;
+    private AppearanceSettings? appearanceSettings;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadAllAsync();
+        loading = false;
+    }
+
+    private async Task LoadAllAsync()
+    {
+        var profileTask = SettingsService.GetProfileAsync();
+        var notifsTask = SettingsService.GetNotificationPrefsAsync();
+        var securityTask = SettingsService.GetSecuritySettingsAsync();
+        var appearanceTask = SettingsService.GetAppearanceAsync();
+
+        await Task.WhenAll(profileTask, notifsTask, securityTask, appearanceTask);
+
+        profile = await profileTask;
+        notificationPrefs = await notifsTask;
+        securitySettings = await securityTask;
+        appearanceSettings = await appearanceTask;
+    }
+
+    private async Task SaveProfileAsync(UserProfile updated)
+    {
+        await SettingsService.SaveProfileAsync(updated);
+        profile = updated;
+    }
+
+    private async Task SaveNotificationsAsync(NotificationPrefs updated)
+    {
+        await SettingsService.SaveNotificationPrefsAsync(updated);
+        notificationPrefs = updated;
+    }
+
+    private async Task ChangePasswordAsync((string Current, string New) args)
+    {
+        await SettingsService.ChangePasswordAsync(args.Current, args.New);
+        securitySettings = await SettingsService.GetSecuritySettingsAsync();
+    }
+
+    private async Task RevokeSessionAsync(string sessionId)
+    {
+        await SettingsService.RevokeSessionAsync(sessionId);
+        securitySettings = await SettingsService.GetSecuritySettingsAsync();
+    }
+
+    private async Task SaveAppearanceAsync(AppearanceSettings updated)
+    {
+        await SettingsService.SaveAppearanceAsync(updated);
+        appearanceSettings = updated;
+    }
+}
+

toolArgs.file_text:
.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 100px);
    gap: 0;
}

::deep .settings-sidebar {
    width: 220px;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
    background-color: #f8f9fa;
    flex-shrink: 0;
}

::deep .settings-sidebar .nav-link {
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    padding: 0.75rem 1.5rem;
    color: #495057;
    font-weight: 500;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
}

::deep .settings-sidebar .nav-link:hover {
    background-color: #e9ecef;
    color: #212529;
}

::deep .settings-sidebar .nav-link.active {
    background-color: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

::deep .settings-section h3 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #dee2e6;
}

